            ["FR-1", "Account discovery and detail: list_ad_accounts, get_ad_account", "Must", "list_ad_accounts returns every account on me/adaccounts with status, currency and lifetime spend; get_ad_account returns balance, spend cap, funding source and timezone for one act_ id"],
            ["FR-2", "Campaign, ad set, ad and creative enumeration: list_campaigns, list_adsets, list_ads, list_creatives", "Must", "Each returns the full edge with its default field set; list_campaigns accepts an effective_status filter; list_adsets and list_ads accept an account, campaign or ad set parent; all accept a comma-separated fields override"],
